import type { GameState, WorldEvent } from "../types";

interface EngineResponse {
  event: {
    title: string;
    summary: string;
    severity: WorldEvent["severity"];
    category: WorldEvent["category"];
    effects: string[];
    shocks?: Record<string, number>;
  };
}

/**
 * Calls the server-side Grok world engine. The API key lives only in the
 * deployment environment (GROK_API_KEY) and is never shipped to the browser.
 * If the route is unavailable — e.g. the static preview build — the local
 * Dungeon Master in engine.ts keeps the world moving.
 */
export async function requestWorldEvent(state: GameState): Promise<WorldEvent | null> {
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), 6_000);
  try {
    const response = await fetch("/api/world-engine", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      signal: controller.signal,
      body: JSON.stringify({
        day: state.world.day,
        tick: state.world.tick,
        sentiment: state.world.sentiment,
        volatility: state.world.volatility,
        index: state.world.index,
        regulatoryPressure: state.government.regulatoryPressure,
        cyberThreat: state.world.cyberThreat,
        player: {
          name: state.player.name,
          netWorth: state.player.cash,
          reputation: state.player.reputation,
        },
        assets: state.assets.map((a) => ({
          id: a.id,
          ticker: a.ticker,
          kind: a.kind,
          price: a.price,
          change: ((a.price - a.prevClose) / a.prevClose) * 100,
          sentiment: a.sentiment,
        })),
        rivals: state.corporate.rivals.map((r) => ({
          name: r.name,
          ceo: r.ceo,
          netWorth: r.netWorth,
          focus: r.focus,
        })),
        isp: { uptime: state.isp.uptime, load: state.isp.nodes.reduce((s, n) => s + n.load, 0) },
        bank: { deposits: state.bank.deposits, reserves: state.bank.reserves, status: state.bank.status },
      }),
    });
    if (!response.ok) return null;
    const data = (await response.json()) as EngineResponse;
    if (!data?.event?.title || !data?.event?.summary) return null;
    return {
      id: `grok-${Date.now().toString(36)}`,
      title: data.event.title,
      summary: data.event.summary,
      severity: data.event.severity ?? "medium",
      category: data.event.category ?? "macro",
      effects: Array.isArray(data.event.effects) ? data.event.effects.slice(0, 5) : [],
      tick: state.world.tick,
      day: state.world.day,
      source: "grok",
    };
  } catch {
    return null;
  } finally {
    window.clearTimeout(timeout);
  }
}

const STORAGE_KEY = "omnilife.syndicate.save.v1";

export function loadSave() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed?.version !== 1 || !parsed?.assets || !parsed?.player) return null;
    return parsed;
  } catch {
    return null;
  }
}

export function persistSave(state: unknown) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch {
    // Storage can be unavailable in private mode. The simulation still runs.
  }
}

export function clearSave() {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch {
    // Ignore.
  }
}

export const fmtMoney = (value: number, decimals = 2) => {
  if (!Number.isFinite(value)) return "$0.00";
  const abs = Math.abs(value);
  const sign = value < 0 ? "-" : "";
  if (abs >= 1_000_000_000) return `${sign}$${(abs / 1_000_000_000).toFixed(decimals)}B`;
  if (abs >= 1_000_000) return `${sign}$${(abs / 1_000_000).toFixed(decimals)}M`;
  if (abs >= 10_000) return `${sign}$${(abs / 1_000).toFixed(1)}K`;
  return `${sign}$${abs.toLocaleString("en-US", {
    minimumFractionDigits: abs < 100 ? decimals : 0,
    maximumFractionDigits: abs < 100 ? decimals : 0,
  })}`;
};

export const fmtFullMoney = (value: number) =>
  `${value < 0 ? "-" : ""}$${Math.abs(Math.round(value)).toLocaleString("en-US")}`;

export const fmtPrice = (value: number) => {
  if (value < 0.01) return `$${value.toFixed(5)}`;
  if (value < 1) return `$${value.toFixed(4)}`;
  return `$${value.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

export const fmtNum = (value: number, decimals = 0) =>
  value.toLocaleString("en-US", { maximumFractionDigits: decimals });

export const fmtCompact = (value: number) => {
  if (Math.abs(value) >= 1_000_000_000) return `${(value / 1_000_000_000).toFixed(1)}B`;
  if (Math.abs(value) >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`;
  if (Math.abs(value) >= 1_000) return `${(value / 1_000).toFixed(1)}K`;
  return `${Math.round(value)}`;
};

export const fmtPct = (value: number, decimals = 2) =>
  `${value >= 0 ? "+" : ""}${value.toFixed(decimals)}%`;

export const fmtTime = (date = new Date()) =>
  date.toLocaleTimeString("en-US", { hour: "2-digit", minute: "2-digit", hour12: false });

export const fmtDate = (date = new Date()) =>
  date.toLocaleDateString("en-US", { month: "short", day: "2-digit", year: "numeric" });

export const signedClass = (value: number) =>
  value > 0 ? "text-mint" : value < 0 ? "text-danger" : "text-white/60";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useReducer,
  useRef,
  type ReactNode,
} from "react";
import type { GameState } from "../types";
import { createInitialState } from "./seed";
import { gameReducer, type Action } from "./reducer";
import { loadSave, persistSave } from "./storage";
import { requestWorldEvent } from "./ai";

interface GameContextValue {
  state: GameState;
  dispatch: (action: Action) => void;
  reset: () => void;
}

const GameContext = createContext<GameContextValue | null>(null);

export function GameProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(
    gameReducer,
    undefined,
    () => (loadSave() as GameState | null) ?? createInitialState(),
  );
  const aiTickRef = useRef(0);
  const aiInFlight = useRef(false);

  // Core simulation clock.
  useEffect(() => {
    if (state.world.paused) return;
    const timer = window.setInterval(() => dispatch({ type: "TICK" }), 5_500);
    return () => window.clearInterval(timer);
  }, [state.world.paused]);

  // Persist every mutation so a refresh never loses an empire.
  useEffect(() => {
    persistSave(state);
  }, [state]);

  // Auto-dismiss the oldest toast.
  useEffect(() => {
    if (state.toasts.length === 0) return;
    const timer = window.setTimeout(
      () => dispatch({ type: "DISMISS_TOAST", id: state.toasts[0].id }),
      5_200,
    );
    return () => window.clearTimeout(timer);
  }, [state.toasts]);

  // Ask the Grok world engine for an event every 12 ticks. The local Dungeon
  // Master has already been generating events in the meantime.
  useEffect(() => {
    const tick = state.world.tick;
    if (tick === 0 || tick % 12 !== 0 || state.world.paused) return;
    if (aiTickRef.current === tick || aiInFlight.current) return;
    aiTickRef.current = tick;
    aiInFlight.current = true;
    requestWorldEvent(state)
      .then((event) => {
        if (event) dispatch({ type: "APPLY_AI_EVENT", event });
      })
      .finally(() => {
        aiInFlight.current = false;
      });
  }, [state]);

  const reset = useCallback(() => {
    dispatch({ type: "RESET" });
  }, []);

  return (
    <GameContext.Provider value={{ state, dispatch, reset }}>{children}</GameContext.Provider>
  );
}

export function useGame() {
  const value = useContext(GameContext);
  if (!value) throw new Error("useGame must be used inside GameProvider");
  return value;
}

