              setPurgeTarget(null);
            }}
          >
            <Trash2 size={11} /> Erase entity
          </Button>
        </div>
      </Modal>

      <Modal open={resetOpen} onClose={() => setResetOpen(false)} title="Reset the timeline" subtitle="All progress will be lost.">
