        </div>
        <div className="mt-4 flex justify-end gap-2">
          <Button variant="ghost" size="sm" onClick={() => setResetOpen(false)}>Cancel</Button>
          <Button
            variant="danger"
            size="sm"
            onClick={() => {
              reset();
              setResetOpen(false);
            }}
          >
            <Power size={11} /> Reset
          </Button>
        </div>
      </Modal>
    </div>
  );
}

