93: export function gameReducer(state: GameState, action: Action): GameState {
94:   const s: GameState = structuredClone(state);
95: 
96:   switch (action.type) {
97:     case "TICK": {
98:       simulateTick(s);
99:       return s;
100:     }
101: 
102:     case "TRADE": {
103:       const asset = quote(s, action.assetId);
104:       const qty = Math.floor(action.qty);
105:       if (!asset || qty <= 0 || !Number.isFinite(qty)) {
106:         addToast(s, "Invalid order size.", "error");
107:         return s;
108:       }
109:       const feeRate = asset.kind === "crypto" ? 0.003 : 0.0012;
110:       const liquidity = asset.kind === "crypto" ? asset.liquidity ?? 500_000 : 8_000_000;
111:       if (action.side === "buy") {
112:         const notional = qty * asset.price;
113:         const total = notional * (1 + feeRate);
114:         if (total > s.player.cash) {
115:           addToast(s, `Insufficient liquidity. Need ${isMoney(total)}.`, "error");
116:           return s;
117:         }
118:         s.player.cash -= total;
119:         const holding = s.holdings[asset.id] ?? { qty: 0, avgCost: asset.price };
120:         holding.avgCost = (holding.avgCost * holding.qty + notional) / (holding.qty + qty);
121:         holding.qty += qty;
122:         s.holdings[asset.id] = holding;
123:         asset.price = applyPriceImpact(asset.price, notional, liquidity, 1);
124:         asset.sentiment = clamp(asset.sentiment + 2, -100, 100);
125:         addLedger(s, `Buy ${qty.toLocaleString()} ${asset.ticker}`, -total, "trade");
126:         addToast(s, `Filled: bought ${qty.toLocaleString()} ${asset.ticker} for ${isMoney(total)}.`, "success");
127:         s.stats.totalTrades += 1;
128:         s.player.xp = Math.min(99.9, s.player.xp + 0.8);
129:       } else {
130:         const holding = s.holdings[asset.id];
131:         if (!holding || holding.qty < qty) {
132:           addToast(s, `You only hold ${(holding?.qty ?? 0).toLocaleString()} ${asset.ticker}.`, "error");
133:           return s;
134:         }
135:         const notional = qty * asset.price;
136:         const proceeds = notional * (1 - feeRate);
137:         holding.qty -= qty;
138:         if (holding.qty === 0) delete s.holdings[asset.id];
139:         s.player.cash += proceeds;
140:         asset.price = applyPriceImpact(asset.price, notional, liquidity, -1);
141:         asset.sentiment = clamp(asset.sentiment - 2, -100, 100);
142:         addLedger(s, `Sell ${qty.toLocaleString()} ${asset.ticker}`, proceeds, "trade");
143:         addToast(s, `Filled: sold ${qty.toLocaleString()} ${asset.ticker} for ${isMoney(proceeds)}.`, "success");
144:         s.stats.totalTrades += 1;
145:         s.player.xp = Math.min(99.9, s.player.xp + 0.8);
146:       }
147:       asset.history.push(asset.price);
148:       if (asset.history.length > 96) asset.history.shift();
149:       s.stats.netWorthHistory.push(netWorth(s));
