154:       const from = quote(s, action.from);
155:       const to = quote(s, action.to);
156:       const holding = s.holdings[action.from];
157:       if (!from || !to || from.id === to.id) {
158:         addToast(s, "Invalid swap route.", "error");
159:         return s;
160:       }
161:       if (!holding || holding.qty < action.amount || action.amount <= 0) {
162:         addToast(s, "Insufficient balance for swap.", "error");
163:         return s;
164:       }
165:       const fromLiquidity = from.liquidity ?? 500_000;
166:       const toLiquidity = to.liquidity ?? 500_000;
167:       const slippage = clamp((action.amount * from.price) / Math.max(1, fromLiquidity) * 0.2, 0, 0.08);
168:       const gross = action.amount * from.price;
169:       const fee = gross * 0.003;
170:       const received = ((gross - fee) * (1 - slippage)) / to.price;
171:       holding.qty -= action.amount;
172:       if (holding.qty <= 0) delete s.holdings[action.from];
173:       const target = s.holdings[action.to] ?? { qty: 0, avgCost: to.price };
174:       target.avgCost = (target.avgCost * target.qty + received * to.price) / (target.qty + received);
