240: export function createLocalEvent(state: GameState): WorldEvent {
241:   const weights = TEMPLATES.map((t) => {
242:     let weight = t.weight;
243:     if (t.category === "regulation" && state.government.regulatoryPressure > 60) weight += 5;
244:     if (t.category === "crime" && state.underworld.heat > 60) weight += 5;
245:     if (t.category === "tech" && state.world.sentiment > 60) weight += 3;
246:     if (t.category === "infrastructure" && state.isp.uptime < 99) weight += 4;
247:     return weight;
248:   });
249:   const total = weights.reduce((a, b) => a + b, 0);
250:   let roll = Math.random() * total;
251:   let template = TEMPLATES[0];
252:   for (let i = 0; i < TEMPLATES.length; i += 1) {
253:     roll -= weights[i];
254:     if (roll <= 0) {
255:       template = TEMPLATES[i];
256:       break;
257:     }
258:   }
259:   return {
260:     id: uid("evt"),
261:     title: template.title,
262:     summary: template.summary,
263:     severity: template.severity,
264:     category: template.category,
265:     effects: template.effects,
266:     tick: state.world.tick,
267:     day: state.world.day,
268:     source: "local",
269:   };
270: }
