272: function shockAsset(state: GameState, id: string, pct: number) {
273:   const asset = state.assets.find((a) => a.id === id);
274:   if (!asset) return;
275:   asset.price = Math.max(0.00005, roundPrice(asset.price * (1 + pct / 100)));
276:   asset.history.push(asset.price);
277:   if (asset.history.length > 96) asset.history.shift();
278:   asset.sentiment = clamp(asset.sentiment + pct / 2, -100, 100);
279: }
