281: export function applyWorldEvent(state: GameState, event: WorldEvent) {
282:   state.world.sentiment = clamp(state.world.sentiment + (event.severity === "critical" ? -6 : 3), 2, 98);
283:   state.world.volatility = clamp(
284:     state.world.volatility + (event.severity === "critical" ? 14 : event.severity === "high" ? 8 : 3),
285:     8,
286:     98,
287:   );
288: 
289:   switch (event.title) {
290:     case "Global Supply Chain Collapse": {
291:       shockAsset(state, "ark", -9);
292:       shockAsset(state, "nva", 3);
293:       const dockside = state.districts.find((d) => d.id === "dockside");
294:       if (dockside) {
295:         dockside.demand = clamp(dockside.demand - 12, 1, 100);
296:         dockside.price = Math.round(dockside.price * 0.97);
297:       }
298:       state.world.sentiment -= 8;
299:       break;
300:     }
301:     case "AI Tech Boom": {
302:       shockAsset(state, "omn", 8);
303:       shockAsset(state, "znt", 4);
304:       state.world.sentiment += 10;
305:       state.corporate.valuation = Math.round(state.corporate.valuation * 1.04);
306:       break;
307:     }
308:     case "Regulatory Crackdown": {
309:       state.assets.filter((a) => a.kind === "crypto").forEach((a) => shockAsset(state, a.id, -12));
310:       state.government.regulatoryPressure = clamp(state.government.regulatoryPressure + 14, 0, 100);
311:       state.underworld.heat = clamp(state.underworld.heat + 6, 0, 100);
312:       state.world.volatility += 12;
313:       break;
314:     }
315:     case "Central Bank Emergency Cut": {
316:       state.assets.filter((a) => a.kind === "stock").forEach((a) => shockAsset(state, a.id, 4));
317:       state.bank.lendingRate = Math.max(2, state.bank.lendingRate - 1.2);
318:       state.world.sentiment += 7;
319:       break;
320:     }
321:     case "Backbone Blackout": {
322:       state.isp.nodes.forEach((n) => {
323:         n.load = clamp(n.load + 28, 0, 140);
324:         n.health = clamp(n.health - 11, 0, 100);
325:         n.status = n.health < 20 ? "offline" : n.health < 55 ? "degraded" : "online";
326:       });
327:       state.isp.reputation = clamp(state.isp.reputation - 7, 0, 100);
328:       shockAsset(state, "gas", 9);
329:       state.world.cyberThreat = clamp(state.world.cyberThreat + 10, 0, 100);
330:       break;
331:     }
332:     case "Media Leak: The Vane Tapes": {
333:       const vane = state.corporate.rivals.find((r) => r.id === "rival-1");
334:       if (vane) vane.sentiment = clamp(vane.sentiment - 22, -100, 100);
335:       shockAsset(state, "znt", 6);
336:       state.media.channels.forEach((c) => {
337:         c.reach = Math.round(c.reach * 1.08);
338:         c.credibility = clamp(c.credibility + 3, 0, 100);
339:       });
340:       state.government.approval = clamp(state.government.approval - 4, 0, 100);
341:       break;
342:     }
343:     case "Meme Liquidity Cascade": {
344:       shockAsset(state, "mema", -26);
345:       state.world.volatility += 14;
346:       state.world.sentiment -= 8;
347:       break;
348:     }
349:     case "Cartel Truce Declared": {
350:       state.underworld.heat = clamp(state.underworld.heat - 10, 0, 100);
351:       state.districts.forEach((d) => {
352:         if (d.crime > 30) d.crime = clamp(d.crime - 4, 0, 100);
353:         d.police = clamp(d.police - 3, 0, 100);
354:       });
355:       break;
356:     }
357:     case "Sovereign Wealth Inflow": {
358:       state.districts.forEach((d) => {
359:         d.demand = clamp(d.demand + 12, 1, 100);
360:       });
361:       ["meridian", "helix"].forEach((id) => {
362:         const d = state.districts.find((x) => x.id === id);
363:         if (d) d.price = Math.round(d.price * 1.06);
364:       });
365:       shockAsset(state, "vlt", 2);
366:       state.world.sentiment += 5;
367:       break;
368:     }
369:     case "Deepfake Governance Scandal": {
370:       state.government.approval = clamp(state.government.approval - 12, 0, 100);
371:       state.media.channels.forEach((c) => (c.credibility = clamp(c.credibility - 8, 0, 100)));
372:       state.media.publicTrust = clamp(state.media.publicTrust - 7, 0, 100);
373:       state.government.regulatoryPressure = clamp(state.government.regulatoryPressure + 4, 0, 100);
374:       break;
375:     }
376:     case "Stablecoin De-Peg Event": {
377:       shockAsset(state, "syn", -18);
378:       shockAsset(state, "omx", 6);
379:       shockAsset(state, "gas", 14);
380:       state.bank.deposits = Math.round(state.bank.deposits * 0.97);
381:       state.bank.reserves = Math.round(state.bank.reserves * 0.97);
382:       break;
383:     }
384:     case "Election Year Spending Spree": {
385:       state.isp.subscribers = Math.round(state.isp.subscribers * 1.05);
386:       state.media.channels.forEach((c) => (c.revenue = Math.round(c.revenue * 1.08)));
387:       state.government.approval = clamp(state.government.approval + 6, 0, 100);
388:       state.government.corpTax = Math.max(5, state.government.corpTax - 1);
389:       break;
390:     }
391:     default: {
392:       // Grok-generated event: apply a coherent category-level shock.
393:       const crypto = state.assets.filter((a) => a.kind === "crypto");
394:       const stocks = state.assets.filter((a) => a.kind === "stock");
395:       const direction = event.severity === "critical" ? -1 : Math.random() > 0.45 ? 1 : -1;
396:       if (event.category === "regulation") {
397:         crypto.forEach((a) => shockAsset(state, a.id, direction * rand(5, 14)));
398:         state.government.regulatoryPressure = clamp(
399:           state.government.regulatoryPressure + Math.abs(direction) * 8,
400:           0,
401:           100,
402:         );
403:       } else if (event.category === "tech") {
404:         shockAsset(state, "omn", 7);
405:         shockAsset(state, "znt", 4);
406:       } else if (event.category === "infrastructure") {
407:         state.isp.nodes.forEach((n) => (n.health = clamp(n.health - 8, 0, 100)));
408:         state.world.cyberThreat = clamp(state.world.cyberThreat + 8, 0, 100);
409:       } else if (event.category === "crime") {
410:         state.underworld.heat = clamp(state.underworld.heat + 6, 0, 100);
411:         state.districts.forEach((d) => (d.crime = clamp(d.crime + 1.5, 0, 100)));
412:       } else if (event.category === "media") {
413:         state.media.channels.forEach((c) => (c.credibility = clamp(c.credibility - 4, 0, 100)));
414:         state.media.publicTrust = clamp(state.media.publicTrust - 3, 0, 100);
415:       } else {
416:         stocks.forEach((a) => shockAsset(state, a.id, direction * rand(1.5, 6)));
417:         crypto.forEach((a) => shockAsset(state, a.id, direction * rand(3, 10)));
418:       }
419:       break;
420:     }
421:   }
422: 
423:   state.world.events.unshift(event);
424:   state.world.events = state.world.events.slice(0, 12);
425:   const tone = event.severity === "critical" ? "negative" : event.category === "tech" ? "positive" : "neutral";
426:   state.world.news.unshift({
427:     id: uid("news"),
428:     text: event.title,
429:     tone,
430:     time: "now",
431:   });
432:   state.world.news = state.world.news.slice(0, 8);
433:   state.world.nextEventIn = randInt(7, 14);
434: }
