583: export function simulateTick(state: GameState) {
584:   if (state.world.paused) return;
585:   state.world.tick += 1;
586:   if (state.world.tick % 48 === 0) {
587:     state.world.day += 1;
588:     state.stats.daysSurvived += 1;
589:   }
590:   const phaseTick = state.world.tick % 48;
591:   state.world.phase = phaseTick < 5 ? "Pre-Market" : phaseTick > 40 ? "After-Hours" : "Open";
592: 
593:   runMarketTick(state);
594: 
595:   // ISP operations
596:   const isp = state.isp;
597:   isp.nodes.forEach((node) => {
598:     const district = state.districts.find((d) => d.id === node.districtId);
599:     const congestion = node.load / Math.max(1, node.capacity);
600:     node.load = clamp(node.load + (Math.random() - 0.48) * 7, 4, node.capacity * 1.4);
601:     if (congestion > 0.92) node.health = clamp(node.health - rand(0.6, 1.8), 0, 100);
602:     else if (node.health < 100 && isp.autoRepair) node.health = clamp(node.health + 0.35, 0, 100);
603:     node.status = node.health <= 0 ? "offline" : node.health < 45 || node.load > node.capacity ? "degraded" : "online";
604:     node.latency = Math.max(2, Math.round(3 + node.load / Math.max(1, node.capacity) * 14 + (100 - node.health) * 0.12 + (district ? district.crime * 0.03 : 0)));
605:   });
606:   const onlineNodes = isp.nodes.filter((n) => n.status !== "offline").length;
607:   const capacity = isp.nodes.reduce((s, n) => s + n.capacity, 0);
608:   const load = isp.nodes.reduce((s, n) => s + n.load, 0);
609:   const quality = onlineNodes / Math.max(1, isp.nodes.length);
610:   isp.uptime = round2(clamp(isp.uptime + (quality - 0.82) * 0.012, 95, 100));
611:   const pricePressure = 1 - clamp((isp.pricePerGb - 0.45) / 1.7, 0, 0.8);
612:   const subscriberDelta = Math.round(isp.subscribers * (quality - 0.72) * 0.0016 * pricePressure);
613:   isp.subscribers = Math.max(1000, isp.subscribers + subscriberDelta);
614:   isp.reputation = clamp(isp.reputation + (quality - 0.75) * 0.18, 0, 100);
615:   const ispRevenue = Math.round(isp.subscribers * isp.pricePerGb * 0.07);
616:   state.player.cash += ispRevenue;
617:   state.stats.lifetimeEarnings += ispRevenue;
618: 
619:   // Bank
620:   if (state.bank.founded) {
621:     const bank = state.bank;
622:     const interestIncome = (bank.loans * bank.lendingRate) / 100 / 1440;
623:     const interestExpense = (bank.deposits * bank.depositRate) / 100 / 1440;
624:     bank.capital += interestIncome - interestExpense;
625:     bank.loans += interestIncome * 0.25;
626:     bank.deposits += interestExpense;
627:     const ratio = (bank.reserves / Math.max(1, bank.deposits)) * 100;
628:     bank.status =
629:       ratio < 4 ? "critical" : ratio < bank.reserveRatio ? "strained" : "stable";
630:     bank.history.push(Math.round(bank.capital));
631:     if (bank.history.length > 48) bank.history.shift();
632:     if (bank.status === "critical" && Math.random() < 0.035) {
633:       const drained = Math.round(bank.deposits * rand(0.12, 0.32));
634:       bank.deposits -= drained;
635:       bank.reserves = Math.max(0, bank.reserves - drained);
636:       bank.runs += 1;
637:       state.world.news.unshift({
638:         id: uid("news"),
639:         text: `Run on ${bank.name}: ${isMoney(drained)} withdrawn in minutes`,
640:         tone: "negative",
641:         time: "now",
642:       });
643:       state.toasts.push({
644:         id: uid("toast"),
645:         message: `Bank run detected at ${bank.name}. ${isMoney(drained)} drained.`,
646:         tone: "error",
647:       });
648:     }
649:     if (bank.status === "critical" && bank.reserves <= 0) {
650:       bank.status = "collapsed";
651:       bank.capital = 0;
652:     }
653:   }
654: 
655:   // Media
656:   state.media.channels.forEach((channel) => {
657:     const drift = (state.media.publicTrust - 50) / 5000;
658:     channel.reach = Math.max(10_000, Math.round(channel.reach * (1 + drift + rand(-0.004, 0.009))));
659:     channel.credibility = clamp(channel.credibility + rand(-0.25, 0.25), 0, 100);
660:     const revenue = Math.round(channel.reach * 0.012 * (0.5 + channel.credibility / 100) + channel.shows.reduce((s, show) => s + show.revenue * 0.02, 0));
661:     channel.revenue = revenue;
662:     state.player.cash += revenue;
663:     state.stats.lifetimeEarnings += revenue;
664:   });
665:   state.media.campaigns = state.media.campaigns
666:     .map((c) => ({ ...c, status: state.world.tick - c.createdAt > 18 ? "completed" as const : c.status }))
667:     .slice(0, 12);
668: 
669:   // Corporate operations
670:   const corp = state.corporate;
671:   if (corp.founded) {
672:     const growth = ((state.world.sentiment - 50) / 2200 + corp.rnd / 9000 + corp.pr / 12000 - corp.rivals.reduce((s, r) => s + r.aggression, 0) / 400000);
673:     corp.valuation = Math.max(250_000, Math.round(corp.valuation * (1 + growth + rand(-0.003, 0.006))));
674:     if (!corp.history) corp.history = [corp.valuation];
675:     corp.history.push(corp.valuation);
676:     if (corp.history.length > 64) corp.history.shift();
677:     const revenue = Math.round((corp.employees * 900 + corp.rnd * 1200) * (0.8 + state.world.sentiment / 250));
678:     corp.revenue = revenue;
679:     state.player.cash += Math.round(revenue * 0.16);
680:     state.stats.lifetimeEarnings += Math.round(revenue * 0.16);
681:   }
682:   corp.rivals.forEach((r) => {
683:     r.netWorth = Math.round(r.netWorth * (1 + rand(-0.004, 0.011)));
684:     r.sentiment = clamp(r.sentiment + rand(-1, 1), -100, 100);
685:   });
686: 
687:   // Underworld
688:   state.underworld.heat = clamp(state.underworld.heat - 0.22 - state.underworld.protection * 0.02, 0, 100);
689:   if (state.underworld.laundering > 0 && state.underworld.dirtyCash > 0) {
690:     const washed = Math.min(state.underworld.dirtyCash, Math.round(state.underworld.laundering * 0.06));
691:     state.underworld.dirtyCash -= washed;
692:     state.player.cash += Math.round(washed * 0.82);
693:     state.underworld.heat = clamp(state.underworld.heat + 0.08, 0, 100);
694:   }
695:   if (state.underworld.heat > 72 && Math.random() < 0.012) {
696:     state.underworld.warrants += 1;
697:     state.government.warrants += 1;
698:     state.world.news.unshift({
699:       id: uid("news"),
700:       text: "Grand jury issues sealed warrant tied to syndicate operations",
701:       tone: "negative",
702:       time: "now",
703:     });
704:   }
705: 
706:   // Government
707:   state.government.regulatoryPressure = clamp(
708:     state.government.regulatoryPressure + rand(-0.25, 0.3) + (state.underworld.heat > 50 ? 0.08 : 0),
709:     0,
710:     100,
711:   );
712:   state.government.bills.forEach((bill) => {
713:     if (bill.status === "voting") {
714:       bill.votes = clamp(bill.votes + randInt(-1, 2), 0, 100);
715:       if (bill.votes >= 50) {
716:         bill.status = "passed";
717:         state.world.news.unshift({
718:           id: uid("news"),
719:           text: `Bill passed: ${bill.title}`,
720:           tone: "neutral",
